import{z as i,x as n,o as l,c as d,q as E,j as A,D as t,d as e,s as o,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"FPGA 布局布线","description":"","frontmatter":{"title":"FPGA 布局布线","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fpga-place-route.md","filePath":"cs/fpga-place-route.md","lastUpdated":1791413859000}'),p={name:"cs/fpga-place-route.md"};function c(T,a,u,P,D,F){const s=n("Mermaid");return l(),d("div",null,[a[2]||(a[2]=E('<h1 id="fpga-布局布线" tabindex="-1">FPGA 布局布线 <a class="header-anchor" href="#fpga-布局布线" aria-label="Permalink to &quot;FPGA 布局布线&quot;">​</a></h1><div class="epigraph"><p>逻辑映射之后仍不知道哪一列 CLB 被占用、哪一段开关盒接通；布局布线决定线延迟，从而改写 STA 的 slack。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Betz, Rose, Marquardt, Architecture and CAD for Deep-Submicron FPGAs 整理</footer></div><p><a href="/cs/fpga-lut-clb">上一课</a>给出 LUT/CLB 砖块。综合网表仍是逻辑连接。缺口是 <strong>place and route</strong>：把实例放到二维阵列，再在布线通道里接通，得到可下载的比特流与真实延迟。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FPGA 布线是预制的分段导线加开关晶体管，不是 ASIC 那样任意金属形状（ASIC 流程后课再讲）。<span class="marginnote">开关盒（switch box）就是布线通道十字路口上的可编程转接器：决定导线从哪个方向接到哪个方向。FPGA 出厂时这些开关全部断开，布局布线工具的工作就是挑出该闭合的那一小部分并写进比特流。</span>布局：邻近的 CLB 应放近，DSP/BRAM 是稀疏硬核，算术单元的乘法器必须「靠」DSP 列。布线失败（不可布）或延迟过大导致<a href="/cs/sta">STA</a> 负 slack。缺口不是再解释 LUT，而是这层物理对应。</p><p>时序驱动布局用 STA 的关键网加权。时钟用专用全局/区域网络，普通信号不要抢时钟树。</p><h3 id="比特流不是「网表的压缩包」" tabindex="-1">比特流不是「网表的压缩包」 <a class="header-anchor" href="#比特流不是「网表的压缩包」" aria-label="Permalink to &quot;比特流不是「网表的压缩包」&quot;">​</a></h3><p>比特流编码的是 SRAM LUT 初值与开关盒通断，格式专有。把 <code>.bit</code> 当另一份 Verilog 阅读，逆向与安全是另一课；本课只承认：功能与时序在 P&amp;R 之后才封闭。</p><p><span class="marginnote">Betz/Rose 的 VPR 教材是 FPGA CAD 经典。Harris 描述设计流程：综合→映射→布局→布线→时序。本课不教某 IDE 的点击顺序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ol><li>映射已在上一课。2. 打包 CLB。3. 布局最小化线长与时序代价。4. 布线分配通道；拥塞则绕路，延迟上升。5. 静态时序签核；失败则改 RTL、约束或再优化。引脚锁定影响边缘延迟。</li></ol>',11)),(l(),A(B,null,{default:t(()=>[o(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22LUT%20%E6%98%A0%E5%B0%84%22%5D%20--%3E%20PL%5B%22%E5%B8%83%E5%B1%80%E5%88%B0%E9%98%B5%E5%88%97%22%5D%0A%20%20PL%20--%3E%20RT%5B%22%E5%BC%80%E5%85%B3%E7%9B%92%E5%B8%83%E7%BA%BF%22%5D%0A%20%20RT%20--%3E%20BIT%5B%22%E6%AF%94%E7%89%B9%E6%B5%81%22%5D%0A%20%20RT%20--%3E%20STA%5B%22%E6%97%B6%E5%BA%8F%E7%AD%BE%E6%A0%B8%22%5D%0A%20%20STA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AHLS%20%E4%BB%8E%E6%9B%B4%E9%AB%98%E5%B1%82%E8%BF%9B%E6%9D%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,[e("跨时钟 FIFO 的两时钟必须各接到合法时钟网络，否则工具用普通布线走时钟，skew 不可控。"),r("span",{class:"marginnote"},"可以把它想象成城市规划：LUT 是楼房，布局决定谁挨着谁，布线是修路。同一对逻辑单元，相邻放置时线延迟可能只有零点几纳秒，隔开半个芯片再绕行就可能涨到几纳秒——同一份网表，两次布线结果 slack 可以完全不同。")],-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,[e("后课 HLS 仍然经过同一 P&R；只是 RTL 由工具生成。ASIC 布局布线没有开关盒，但「时序闭合」同一目标。本课把 FPGA 的物理闭环钉死，让后面的功耗与验证知道延迟来自布线，不是来自 "),r("code",null,"#delay"),e("。")],-1)),(l(),A(B,null,{default:t(()=>[o(s,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRY%5B%22%E9%A6%96%E6%AC%A1%E5%B8%83%E7%BA%BF%E5%B0%9D%E8%AF%95%22%5D%20--%3E%20CONG%7B%22%E9%80%9A%E9%81%93%E6%8B%A5%E5%A1%9E%3F%22%7D%0A%20%20CONG%20--%3E%7C%22%E6%98%AF%22%7C%20RIP%5B%22%E6%8B%86%E7%BA%BF%E9%87%8D%E5%B8%83%EF%BC%9A%E7%BB%95%E5%BC%80%E6%8B%A5%E6%8C%A4%E9%80%9A%E9%81%93%22%5D%0A%20%20RIP%20--%3E%20DELAY%5B%22%E7%BA%BF%E5%BB%B6%E8%BF%9F%E4%B8%8A%E5%8D%87%22%5D%0A%20%20DELAY%20--%3E%20STA2%5B%22STA%20%E5%A4%8D%E6%9F%A5%20slack%22%5D%0A%20%20STA2%20--%3E%7C%22%E8%B4%9F%20slack%22%7C%20FIX%5B%22%E6%94%B9%E7%BA%A6%E6%9D%9F%E6%88%96%E6%94%B9%20RTL%22%5D%0A%20%20FIX%20--%3E%20TRY%0A%20%20CONG%20--%3E%7C%22%E5%90%A6%22%7C%20DONE%5B%22%E5%B8%83%E7%BA%BF%E6%88%90%E5%8A%9F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p><span class="marginnote">初学者容易以为延迟由代码里写的 <code>#delay</code> 决定；实际上 FPGA 的关键路径延迟大头来自布线段和开关盒，LUT 本身只占一小部分。这就是为什么同一份 RTL 换个工具版本或换个器件，时序报告会整条路径地变化。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论部分重配置的全部安全模型，不把 PCB 走线当 FPGA 内部布线。不进入光刻分辨率与金属层——FPGA 对用户是已造好的阵列。</p><p>后课默认：FPGA 时序在布局布线后才真实；DSP/BRAM 位置是一等约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LUT 映射之后还要放置 CLB 并接通开关盒。</li><li>线延迟进入 STA；时钟走专用网络。</li><li>比特流是配置 SRAM，不是可读网表。</li><li>出处：Harris and Harris；Betz, Rose, Marquardt。</li></ul>',6))])}const f=i(p,[["render",c]]);export{m as __pageData,f as default};
